import{_ as r,l as n,o as e,c as l,v as t,p as s,x as i,d,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"指针认证 PAC","description":"","frontmatter":{"title":"指针认证 PAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pointer-authentication.md","filePath":"cs/pointer-authentication.md","lastUpdated":1789023840000}'),c={name:"cs/pointer-authentication.md"};function h(u,a,P,_,C,E){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="指针认证-pac" tabindex="-1">指针认证 PAC <a class="header-anchor" href="#指针认证-pac" aria-label="Permalink to &quot;指针认证 PAC&quot;">​</a></h1><div class="epigraph"><p>ARMv8.3 把短 MAC 塞进指针闲置位：改地址而不重签，使用时校验失败。密钥在内核/EL 管理，用户态任意写不再能静默改返回地址或函数指针。</p><footer>—— ARM ARM 对 PAC 的描述；Qualcomm/Apple 的工程叙述；对照 Liljestrand 等对 PAC 的分析</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/shadow-stack-cet">CET</a>是 x86 的硬件 CFI。缺口是<strong>ARM 的指针签名</strong>：PAC。本课讲签什么、密钥在哪，不给伪造 PAC 的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>64 位指针有闲置位。PAC：对地址与上下文（SP）算短标签。返回地址、函数指针可签。缺口是密钥泄漏与位宽（碰撞）——只陈述余量有限，要配合其他缓解。</p><h3 id="不是加密内存" tabindex="-1">不是加密内存 <a class="header-anchor" href="#不是加密内存" aria-label="Permalink to &quot;不是加密内存&quot;">​</a></h3><p>数据载荷仍明文。PAC 管指针完整性。</p><p><span class="marginnote">ARM Pointer Authentication。Linux <code>HWCAP_PACA</code>。本课禁止绕过教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 CET：一个管边，一个管指针值。二者可叠。指出内核与用户密钥分离。下一课：从硬件缓解走到语言迁移。</p>',12)),(e(),s(A,null,{default:i(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8C%87%E9%92%88%22%5D%20--%3E%20SIGN%5B%22PAC%20%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIGN%20--%3E%20USE%5B%22%E8%AE%A4%E8%AF%81%E5%90%8E%E4%BD%BF%E7%94%A8%22%5D%0A%20%20TAMPER%5B%22%E6%94%B9%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20FAIL%5B%22%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制数据的完整性终于有了指令级标签。根治仍是少写 C。下一课内存安全语言迁移：类型与所有权进编译器。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析 PAC 碰撞构造。内存安全语言下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CET 钉边；PAC 钉指针值。</li><li>短 MAC 在闲置位；密钥在更高特权。</li><li>余量有限，须叠加。</li><li>下一课内存安全语言。</li><li>出处：ARM ARM；Liljestrand et al.；对照 Intel CET。</li></ul>',8))])}const T=r(c,[["render",h]]);export{f as __pageData,T as default};
